mapper.select:
SELECT 
FROM schedule s
WHERE s.schedule_id = #{scheduleId}

SELECT 
FROM schedule s
WHERE s.status <> 'CANCELED'
  AND s.start_time < #{to}
  AND s.end_time > #{from}
  AND (
        s.user_id = #{userId}
        OR EXISTS (SELECT 1 FROM schedule_member m
                   WHERE m.schedule_id = s.schedule_id
                     AND m.user_id = #{userId}
                     AND m.status = 'ACCEPTED')
      )
ORDER BY s.start_time, s.schedule_id

SELECT 
FROM schedule s
WHERE s.status <> 'CANCELED'
  AND s.start_time < #{end}
  AND s.end_time > #{start}

  AND s.schedule_id <> #{excludeId}

  AND (
        s.user_id = #{userId}
        OR EXISTS (SELECT 1 FROM schedule_member m
                   WHERE m.schedule_id = s.schedule_id
                     AND m.user_id = #{userId}
                     AND m.status = 'ACCEPTED')
      )
ORDER BY s.start_time

mapper.update:
UPDATE schedule
SET start_time = #{start},
    end_time = #{end}
WHERE schedule_id = #{scheduleId}

UPDATE schedule
SET status = #{status}
WHERE schedule_id = #{scheduleId}

UPDATE schedule_member
SET status = #{status},
    responded_at = CURRENT_TIMESTAMP
WHERE schedule_id = #{scheduleId}
  AND user_id = #{userId}
  AND status = 'PENDING'
